// Transform raw quiz bank (quiz_bank_risk_management_300.json) → QuizQuestionItem[]
interface RawRiskQuestion {
  id: string;
  chapter: number;
  topic: string;
  bloomLevel: string;
  difficulty: string;
  question: string;
  options: string[];
  correctAnswer: number;
  explanation: string;
  sourceReference: string;
  correctLetter: string;
}
const RISK_MANAGEMENT_QUESTIONS: QuizQuestionItem[] = (riskManagementQuestionsRaw as RawRiskQuestion[]).map((q) => ({
  question: q.question,
  answers: q.options,
  correct: q.correctAnswer,
  chapter: q.chapter,
  difficulty: q.difficulty,
  explanation: q.explanation,
}));

export interface QuizQuestionItem {
  question: string;
  answers: string[];
  correct: number; // 0 = A, 1 = B, 2 = C, 3 = D
  chapter?: number | null;
  difficulty?: string;
  explanation?: string;
}

export interface QuizModeCard {
  index: number;
  value: string;
  title: string;
  desc: string;
  badge: string;
}

export interface OnlineExamModeConfig {
  count: number;
  minutes: number;
  label: string;
}

export interface OnlineExamSubjectConfig {
  key: string;
  label: string;
  linked_route?: string;
  use_linked_bank?: boolean;
  enabled: boolean;
  questions: QuizQuestionItem[];
}

export interface OnlineExamConfig {
  header_badge: string;
  header_title: string;
  header_subtitle: string;
  step1_title: string;
  show_detailed_answers: boolean;
  modes: OnlineExamModeConfig[];
  subjects: OnlineExamSubjectConfig[];
}

export interface QuizTargetMeta {
  id: string; // e.g. 'online:principles-of-marketing'
  group: 'page' | 'online';
  title: string;
  route_path: string;
  question_count: number;
  mode_count: number;
}

