export function getDefaultOnlineExamConfig(): OnlineExamConfig {
  return {
    header_badge: '',
    header_title: 'THI ONLINE',
    header_subtitle: 'Vui lòng chọn môn học và thi, thời gian thi 60 phút/50 câu',
    step1_title: 'Đăng nhập',
    show_detailed_answers: false,
    modes: [
      { count: 50, minutes: 60, label: 'Đề thi chuẩn (50 câu — 60 phút)' },
      { count: 20, minutes: 30, label: 'Đề kiểm tra (20 câu — 30 phút)' },
      { count: 10, minutes: 15, label: 'Đề ôn tập tiêu chuẩn (10 câu — 15 phút)' },
      { count: 5, minutes: 8, label: 'Đề luyện phản xạ nhanh (5 câu — 8 phút)' },
    ],
    subjects: JSON.parse(JSON.stringify(DEFAULT_ONLINE_SUBJECTS)),
  };
}

export function getOnlineExamConfig(): OnlineExamConfig {
  const raw = getOnlineExamConfigRaw();
  const def = getDefaultOnlineExamConfig();
  if (!raw || !raw.trim()) return def;
  try {
    const parsed = JSON.parse(raw) as Partial<OnlineExamConfig>;
    return {
      header_badge: parsed.header_badge || def.header_badge,
      header_title: parsed.header_title || def.header_title,
      header_subtitle: parsed.header_subtitle || def.header_subtitle,
      step1_title: parsed.step1_title || def.step1_title,
      show_detailed_answers: parsed.show_detailed_answers !== undefined ? Boolean(parsed.show_detailed_answers) : false,
      modes: Array.isArray(parsed.modes) && parsed.modes.length > 0 ? parsed.modes : def.modes,
      subjects:
        Array.isArray(parsed.subjects) && parsed.subjects.length > 0
          ? parsed.subjects.map((s) => {
              const defSub = def.subjects.find((d) => d.key === s.key);
              const mergedQuestions =
                Array.isArray(s.questions) && s.questions.length >= (defSub?.questions.length || 50)
                  ? s.questions
                  : defSub?.questions || s.questions || [];
              return {
                ...defSub,
                ...s,
                use_linked_bank: s.linked_route || defSub?.linked_route ? (s.use_linked_bank ?? true) : false,
                questions: mergedQuestions,
              };
            })
          : def.subjects,
    };
  } catch {
    return def;
  }
}

export function saveOnlineExamConfig(cfg: OnlineExamConfig): void {
  saveOnlineExamConfigRaw(JSON.stringify(cfg));
}

export function extractQuestionBankFromJs(js: string): QuizQuestionItem[] {
  if (!js) return [];
  const start = js.indexOf('const questionBank');
  if (start === -1) return [];
  const arrStart = js.indexOf('[', start);
  const endIdx = js.indexOf('];', arrStart);
  if (arrStart === -1 || endIdx === -1) return [];
  const rawArr = js.slice(arrStart, endIdx + 1);
  try {
    const cleaned = rawArr
      .split(/\r?\n/)
      .filter((line) => !/^\s*\/\//.test(line))
      .join('\n')
      .replace(/,(\s*[\]\}])/g, '$1');
    const parsed = JSON.parse(cleaned);
    if (!Array.isArray(parsed)) return [];
    return parsed.map((q) => ({
      question: String(q.question || q.q || '').trim(),
      answers: Array.isArray(q.answers)
        ? q.answers.map((a: any) => String(a ?? '').trim())
        : Array.isArray(q.options)
          ? q.options.map((a: any) => String(a ?? '').trim())
          : ['', '', '', ''],
      correct: typeof q.correct === 'number' ? q.correct : typeof q.ans === 'number' ? q.ans : 0,
      chapter: q.chapter !== undefined && q.chapter !== null ? Number(q.chapter) || null : null,
      difficulty: q.difficulty ? String(q.difficulty) : 'Trung bình',
      explanation: q.explanation ? String(q.explanation) : '',
    }));
  } catch {
    return [];
  }
}

export function replaceQuestionBankInJs(js: string, questions: QuizQuestionItem[]): string {
  const cleanQuestions = questions.map((q) => {
    const item: Record<string, any> = {
      question: String(q.question || '').trim(),
      answers: Array.isArray(q.answers) ? q.answers.map((a) => String(a ?? '').trim()) : ['', '', '', ''],
      correct: Math.max(0, Math.min(3, Number(q.correct) || 0)),
    };
    if (q.chapter !== undefined && q.chapter !== null && Number(q.chapter) > 0) {
      item.chapter = Number(q.chapter);
    } else {
      item.chapter = 1;
    }
    if (q.difficulty) {
      item.difficulty = String(q.difficulty);
    }
    if (q.explanation) {
      item.explanation = String(q.explanation);
    }
    return item;
  });

  const serialized = `const questionBank = ${JSON.stringify(cleanQuestions, null, 2)};`;
  if (!js) return serialized;
  const start = js.indexOf('const questionBank');
  if (start === -1) return `${serialized}\n${js}`;
  const arrStart = js.indexOf('[', start);
  const endIdx = js.indexOf('];', arrStart);
  if (arrStart === -1 || endIdx === -1) return js;
  return js.slice(0, start) + serialized + js.slice(endIdx + 2);
}

export function extractModeCardsFromHtml(html: string): QuizModeCard[] {
  if (!html) return [];
  const modes: QuizModeCard[] = [];
  const regex = /<label\s+[^>]*class="[^"]*mode-(?:card|item)[^"]*"[^>]*>[\s\S]*?<\/label>/gi;
  let m: RegExpExecArray | null;
  let idx = 0;
  while ((m = regex.exec(html)) !== null) {
    const raw = m[0];
    const valMatch = raw.match(/value="([^"]*)"/i) || raw.match(/data-value="([^"]*)"/i);
    const titleMatch = raw.match(/<p\s+class="(?:mode-title|title)"[^>]*>([\s\S]*?)<\/p>/i);
    const descMatch = raw.match(/<p\s+class="(?:mode-desc|desc)"[^>]*>([\s\S]*?)<\/p>/i);
    const badgeMatch = raw.match(/<span\s+class="badge"[^>]*>([\s\S]*?)<\/span>/i);
    modes.push({
      index: idx++,
      value: valMatch ? valMatch[1] : String(idx),
      title: titleMatch ? titleMatch[1].replace(/\s+/g, ' ').trim() : '',
      desc: descMatch ? descMatch[1].replace(/\s+/g, ' ').trim() : '',
      badge: badgeMatch ? badgeMatch[1].replace(/\s+/g, ' ').trim() : '',
    });
  }
  return modes;
}

export function replaceModeCardsInHtml(html: string, updatedModes: QuizModeCard[]): string {
  if (!html || !Array.isArray(updatedModes) || updatedModes.length === 0) return html;
  const mapByIdx = new Map<number, QuizModeCard>();
  updatedModes.forEach((m, i) => mapByIdx.set(typeof m.index === 'number' ? m.index : i, m));

  let currentIdx = 0;
  const regex = /<label\s+[^>]*class="[^"]*mode-(?:card|item)[^"]*"[^>]*>[\s\S]*?<\/label>/gi;
  return html.replace(regex, (block) => {
    const upd = mapByIdx.get(currentIdx++);
    if (!upd) return block;
    let out = block;
    if (upd.title !== undefined) {
      out = out.replace(/(<p\s+class="(?:mode-title|title)"[^>]*>)[\s\S]*?(<\/p>)/i, `$1${upd.title}$2`);
    }
    if (upd.desc !== undefined) {
      out = out.replace(/(<p\s+class="(?:mode-desc|desc)"[^>]*>)[\s\S]*?(<\/p>)/i, `$1${upd.desc}$2`);
    }
    if (upd.badge !== undefined && /<span\s+class="badge"/i.test(out)) {
      out = out.replace(/(<span\s+class="badge"[^>]*>)[\s\S]*?(<\/span>)/i, `$1${upd.badge}$2`);
    }
    return out;
  });
}

export function getAllQuizTargetsSummary(): QuizTargetMeta[] {
  const list: QuizTargetMeta[] = [];
  const onlineCfg = getOnlineExamConfig();

  for (const sub of onlineCfg.subjects) {
    let qCount = sub.questions.length;
    if ((sub.use_linked_bank !== false || qCount < 50) && sub.linked_route) {
      const p = getPageByPath(sub.linked_route);
      if (p) {
        const linkedQs = extractQuestionBankFromJs(p.custom_js || '');
        if (linkedQs.length > qCount) qCount = linkedQs.length;
      }
    }
    list.push({
      id: `online:${sub.key}`,
      group: 'online',
      title: `[Thi Online] ${sub.label}`,
      route_path: `/ngan-hang-de-thi?subject=${sub.key}`,
      question_count: qCount,
      mode_count: onlineCfg.modes.length,
    });
  }

  for (const item of QUIZ_PAGE_ROUTES) {
    const p = getPageByPath(item.route_path);
    const qs = p ? extractQuestionBankFromJs(p.custom_js || '') : [];
    const modes = p ? extractModeCardsFromHtml(p.html_content || '') : [];
    list.push({
      id: `page:${item.route_path}`,
      group: 'page',
      title: `[Đề Thi Theo Chương] ${item.label}`,
      route_path: item.route_path,
      question_count: qs.length,
      mode_count: modes.length,
    });
  }

  return list;
}

export function parseBulkQuestionsText(rawText: string): QuizQuestionItem[] {
  const trimmed = rawText.trim();
  if (trimmed.startsWith('[') || trimmed.startsWith('{')) {
    try {
      const parsedJson = JSON.parse(trimmed);
      const arr = Array.isArray(parsedJson)
        ? parsedJson
        : Array.isArray(parsedJson?.questions)
          ? parsedJson.questions
          : [];
      if (arr.length > 0) {
        const jsonResults: QuizQuestionItem[] = [];
        for (const item of arr) {
          const qText = String(item.question || item.q || '').trim();
          const ansList = Array.isArray(item.answers)
            ? item.answers.map((x: any) => String(x ?? '').trim())
            : Array.isArray(item.options)
              ? item.options.map((x: any) => String(x ?? '').trim())
              : [];
          if (!qText || ansList.length < 2) continue;
          const rawCorr = item.correct ?? item.ans ?? 0;
          let corrIdx = 0;
          if (typeof rawCorr === 'number') {
            corrIdx = Math.max(0, Math.min(3, rawCorr));
          } else if (typeof rawCorr === 'string') {
            const up = rawCorr.toUpperCase().trim();
            if (up === 'B') corrIdx = 1;
            else if (up === 'C') corrIdx = 2;
            else if (up === 'D') corrIdx = 3;
            else corrIdx = Math.max(0, Math.min(3, Number(up) || 0));
          }
          jsonResults.push({
            question: qText,
            answers: ansList.slice(0, 4),
            correct: corrIdx,
            chapter: Number(item.chapter) > 0 ? Number(item.chapter) : 1,
            difficulty: String(item.difficulty || 'Trung bình').trim(),
            explanation: String(item.explanation || '').trim(),
          });
        }
        if (jsonResults.length > 0) return jsonResults;
      }
    } catch {
      // Fallback to text/CSV parsing below
    }
  }

  const lines = rawText
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter(Boolean);

  const results: QuizQuestionItem[] = [];
  for (const line of lines) {
    // Skip header line
    if (/^(stt|câu\s*hỏi|question|nội\s*dung)/i.test(line) && /(đáp\s*án|answer|option\s*a)/i.test(line)) {
      continue;
    }

    const parts = line.split(/\t|\|/).map((s) => s.trim());
    let cols = parts;
    if (cols.length < 5) {
      // Fallback to CSV split (respecting basic quotes)
      const csvMatches = line.match(/(".*?"|[^",\s]+)(?=\s*,|\s*$)/g);
      if (csvMatches && csvMatches.length >= 5) {
        cols = csvMatches.map((c) => c.replace(/^"|"$/g, '').replace(/""/g, '"').trim());
      } else {
        cols = line.split(',').map((s) => s.trim());
      }
    }

    if (cols.length < 5) continue;

    // If first column is a pure number (STT), shift it
    let offset = 0;
    if (/^\d+$/.test(cols[0]) && cols.length >= 6) {
      offset = 1;
    }

    const qText = cols[offset] || '';
    const ansA = cols[offset + 1] || '';
    const ansB = cols[offset + 2] || '';
    const ansC = cols[offset + 3] || '';
    const ansD = cols[offset + 4] || '';
    const rawCorrect = (cols[offset + 5] || 'A').toUpperCase().trim();
    const rawChapter = cols[offset + 6] || '1';
    const rawExplanation = cols[offset + 7] || '';

    if (!qText || (!ansA && !ansB)) continue;

    let correctIdx = 0;
    if (rawCorrect === 'B' || rawCorrect === '1' || rawCorrect === '2') {
      correctIdx = rawCorrect === 'B' ? 1 : Number(rawCorrect) === 2 ? 1 : 1;
    }
    if (rawCorrect === 'A' || rawCorrect === '0' || rawCorrect === '1') {
      correctIdx = rawCorrect === 'A' || rawCorrect === '0' || rawCorrect === '1' ? 0 : 0;
    }
    if (/^A$/i.test(rawCorrect)) correctIdx = 0;
    else if (/^B$/i.test(rawCorrect)) correctIdx = 1;
    else if (/^C$/i.test(rawCorrect)) correctIdx = 2;
    else if (/^D$/i.test(rawCorrect)) correctIdx = 3;
    else if (/^[1-4]$/.test(rawCorrect)) correctIdx = Number(rawCorrect) - 1;
    else if (/^0$/.test(rawCorrect)) correctIdx = 0;

    const chapNum = parseInt(String(rawChapter).replace(/\D+/g, ''), 10) || 1;

    results.push({
      question: qText,
      answers: [ansA, ansB, ansC, ansD],
      correct: correctIdx,
      chapter: chapNum,
      difficulty: 'Trung bình',
      explanation: rawExplanation,
    });
  }

  return results;
}

export function updateSitePageQuizData(
  routePath: string,
  newQuestions?: QuizQuestionItem[],
  newModes?: QuizModeCard[]
): boolean {
  const page = getPageByPath(routePath);
  if (!page) return false;

  const updatedHtml = newModes ? replaceModeCardsInHtml(page.html_content || '', newModes) : page.html_content || '';
  const updatedJs = newQuestions ? replaceQuestionBankInJs(page.custom_js || '', newQuestions) : page.custom_js || '';

  db.prepare(`
    UPDATE site_pages
    SET title = ?, html_content = ?, custom_css = ?, custom_js = ?, updated_at = CURRENT_TIMESTAMP
    WHERE route_path = ?
  `).run(page.title, updatedHtml, page.custom_css || '', updatedJs, page.route_path);

  return true;
}
